const preferencesFor=a=>({...defaults,...globalPrefs,...(prefs[a?.id]||{}),color:accountColor(a||active(),prefs)});
async function hydratePrivatePreferences(id){if(!native||id==='demo')return;const legacy=Object.fromEntries(privatePreferenceKeys.filter(key=>prefs[id]?.[key]!==undefined).map(key=>[key,prefs[id][key]]));const value=await invoke('secure_preferences_get',{account:id});if(!Object.keys(value||{}).length&&Object.keys(legacy).length){await invoke('secure_preferences_save',{account:id,prefs:legacy});prefs[id]={...prefs[id],...legacy}}else prefs[id]={...prefs[id],...(value||{})};persistPublicPreferences()}
async function savePrivatePreferences(id,value){if(native&&id!=='demo')await invoke('secure_preferences_save',{account:id,prefs:value});prefs[id]={...prefs[id],...value};persistPublicPreferences()}
let S={accounts:[],account:'demo',page:'mail',folder:'inbox',messages:[],selected:null,contacts:[],events:[],rules:[],query:'',cursor:null,loading:false,error:'',demo:true,month:new Date(new Date().getFullYear(),new Date().getMonth(),1)};
