const initials=s=>String(s||'?').split(/[\s@]+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const name=s=>String(s||'Unknown sender').split('<')[0].trim();
const email=s=>(String(s||'').match(/<([^>]+)>/)||[])[1]||String(s||'').trim();
