const tabDrag=createTabDrag({getAccounts:()=>S.accounts,onError:fail,onDetach:native?transferDraggedAccount:null,onExternalMove:point=>tabTransfer.externalMove(point),onExternalEnd:()=>tabTransfer.clearPreview(),onDragState:()=>tabTransfer.updateBlocked(),onCommit:ids=>{S.accounts=restoreAccountOrder(S.accounts,ids);localStorage.setItem('goodmail-tab-order',JSON.stringify(mergeVisibleTabOrder(read('goodmail-tab-order',[]),ids)))},onRender:id=>{render();if(id)focusAccountTab(id)}});
const writingAction=createWritingTools({$,esc,button,pref:()=>preferencesFor(mailUi?.sender()||active()),invoke,toast,active:()=>mailUi?.sender()||active()});
