const accountSignIn=createAccountSignIn({native,invoke,$,modal,onConnected:async account=>{S.accounts=await invoke('accounts');restoreTabOrder();ensureAccountColors();$('#modal').close();await switchAccount(account.id,{force:true});toast('Account connected')}});
const manualAccounts=createManualAccounts({native,invoke,$,modal,onConnected:async account=>{S.accounts=await invoke('accounts');restoreTabOrder();ensureAccountColors();$('#modal').close();await switchAccount(account.id,{force:true,view:{page:'mail',folder:'inbox',query:'',selected:null}});toast('Account connected')}});
