const expandedSettings=createExpandedSettings({getState:()=>S,native,invoke,$,modal,button,toast,render,load,active,preferences:preferencesFor,defaults,getAccountPreferences:id=>Object.fromEntries(privatePreferenceKeys.filter(key=>prefs[id]?.[key]!==undefined).map(key=>[key,prefs[id][key]])),savePrivatePreferences,savePublicSettings:value=>{globalPrefs=value;localStorage.setItem('goodmail-settings',JSON.stringify(value));setRefresh()},clearLegacyDemo:()=>localStorage.removeItem('goodmail-demo')});
