async function load(append=false){
 if(noAccountsInWindow()){S.loading=false;render();return}const gen=++generation,account=S.account,page=S.page;
 if(!pageSupported()||page==='mail'&&!can('mailRead')){S.loading=false;S.error='';S.messages=[];S.cursor=null;render();return}
 if(page==='mail'&&!S.unified&&!S.folder.startsWith('custom:')&&!visibleFolders().some(([id])=>id===S.folder))S.folder='inbox';
 if(page==='mail'&&!can('mailSearch'))S.query='';S.loading=true;S.error='';render();
 try{
  if(workspacePages.has(page)){await expandedWorkspace.loadPage();return}
  if(page==='settings'){await cloudDrives.refresh();await expandedSettings.refresh();if(native&&!S.demo)await hydratePrivatePreferences(account)}
  if(S.demo){if(page==='mail'){S.messages=demo.messages.filter(message=>(S.folder==='starred'?message.starred:message.folder===S.folder)&&`${message.from} ${message.subject} ${message.body}`.toLowerCase().includes(S.query.toLowerCase())).map(message=>({...message,accountId:'demo',accountEmail:active().email}));S.cursor=null}S.contacts=demo.contacts;S.events=demo.events;S.rules=demo.rules;S.calendars=[{id:'demo',name:'Demo calendar',primary:true,canEdit:true}];return}
  if(page==='mail'){
   const value=await invoke(S.unified?'workspace_mail_list':'mail_list',{...(S.unified?{}:{account}),folder:S.folder,query:S.query,cursor:append?S.cursor:null,refresh:S.forceRefresh===true});if(gen!==generation)return;
   const items=(value.items||[]).map(message=>({...message,accountId:message.accountId||account,accountEmail:message.accountEmail||active().email}));S.messages=append?[...S.messages,...items]:items;S.cursor=value.cursor;S.cached=!!value.cached;S.offline=!!value.offline;S.syncNotice=value.offline?'Offline · showing encrypted local cache':value.errors?.length?value.errors.map(error=>error.message||error).join(' · '):value.notice||'';await expandedWorkspace.loadFolders();
  }else if(page==='contacts'){const value=await groupware.loadContacts();if(gen!==generation)return;S.contacts=value.contacts;S.contactGroups=value.groups}
  else if(page==='calendar'){const begin=new Date(S.month);begin.setDate(-6);const end=new Date(S.month.getFullYear(),S.month.getMonth()+1,8);const events=await groupware.loadCalendar(begin.toISOString(),end.toISOString());if(gen!==generation)return;S.events=events}
  else if(page==='rules'){const result=await invoke('mail_rule_list',{account});S.rules=Array.isArray(result)?result:result.items||[];S.ruleNotice=result.notice||''}
 }catch(error){if(gen===generation)S.error=String(error)}finally{S.forceRefresh=false;if(gen===generation){S.loading=false;render()}}
}
