let searchTimer;
document.addEventListener('input',e=>{if(e.target.id==='search'){S.query=e.target.value;if(S.page==='contacts'){const input=e.target;const pos=input.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}else{clearTimeout(searchTimer);searchTimer=setTimeout(()=>load(),500)}}});
document.addEventListener('change',async e=>{if(e.target.id==='contact-import-file'){const preview=$('#import-preview');try{const file=e.target.files[0];if(!file)return;if(file.size>5_000_000)throw 'Choose a file smaller than 5 MB.';const imported=parseContacts(await file.text(),file.name);if(!S.demo)S.contacts=await invoke('contacts_list',{account:S.account});const seen=new Set(S.contacts.map(contactKey)),pending=[];for(const c of imported){const key=contactKey(c);if(!seen.has(key)){pending.push(c);seen.add(key)}}$('#modal')._import=pending;preview.innerHTML='<div class="notice">'+pending.length+' new contacts · '+(imported.length-pending.length)+' duplicates skipped.</div>'+pending.slice(0,8).map(c=>'<p class="muted">'+esc(c.name)+' · '+esc(c.email)+' · '+esc(c.phone)+'</p>').join('')+(pending.length>8?'<p class="muted">And '+(pending.length-8)+' more…</p>':'')+'<div class="modal-footer">'+button('Cancel','close')+button('Import '+pending.length+' contacts','confirm-import','primary',pending.length?'':'disabled')+'</div>';}catch(err){preview.innerHTML='<p class="error">'+esc(err)+'</p>'}return;}if(e.target.id==='account'){await switchAccount(e.target.value)}if(e.target.id==='files'){
 const input=e.target,selected=[...input.files],dialog=$('#modal'),draftToken=dialog._composeToken,bodyNode=$('#body'),owner=mailUi.sender().id,job={token:draftToken};input.value='';
 if(!selected.length)return;
 localAttachmentJobs.add(job);$('#attachment-status').textContent='Reading selected files…';
 try{
  const max=mailUi.sender().provider==='outlook'?3_000_000:9_000_000;
  if(selected.reduce((sum,file)=>sum+file.size,0)+files.reduce((sum,file)=>sum+attachmentByteLength(file),0)>max)throw Error('Attachments exceed '+(max/1_000_000)+' MB total.');
  const additions=await Promise.all(selected.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Could not read '+file.name));reader.onload=()=>resolve({name:file.name,data:String(reader.result).split(',')[1],size:file.size});reader.readAsDataURL(file)})));
  if(!dialog.open||dialog._composeToken!==draftToken||$('#body')!==bodyNode||mailUi.sender().id!==owner){toast('The draft changed. The selected files were not attached.');return}
  let next=files;for(const file of additions)next=appendAttachment(next,file,mailUi.sender().provider);files=next;renderAttachments();$('#attachment-status').textContent='';
 }catch(error){if(dialog.open&&dialog._composeToken===draftToken&&$('#attachment-status'))$('#attachment-status').textContent=String(error);else toast(String(error))}
 finally{localAttachmentJobs.delete(job)}
}});
document.addEventListener('keydown',e=>{if(tabDrag.isInteracting())return;if(!$('#modal').open){const onTab=e.target.closest?.('[data-account-tab]');const key=((e.ctrlKey||e.metaKey)&&e.key==='Tab')?(e.shiftKey?'ArrowLeft':'ArrowRight'):onTab?e.key:null;const next=key?nextAccountTab(S.accounts,onTab?.dataset.accountTab||S.account,key):null;if(next){e.preventDefault();switchAccount(next).catch(fail);focusAccountTab(next);return}}if((e.ctrlKey||e.metaKey)&&e.key==='n'){e.preventDefault();if(!noAccountsInWindow())compose().catch(fail)}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#search')?.focus()}});
